fun main() {
    val c = 'a'
    println(c + 1)
    println(c.code)
    println('A'.lowercaseChar() to 'z'.uppercaseChar())
    println('5'.isDigit() to 'x'.isLetter() to ' '.isWhitespace())
    println('5'.digitToInt() + 1)
    println(7.digitToChar())
    println('a'..'e')
    println(('a'..'e').toList())
    println('e' - 'a')
    println(('a' + 25))
    println('Z'.isUpperCase() to 'z'.isLowerCase())
    println('_'.isLetterOrDigit())
    println(Char(66))
    println('c'.compareTo('a'))
    println("hello".map { it.uppercaseChar() }.joinToString(""))
    println("hello".count { it in "aeiou" })
    println("h-e-y".filter { it.isLetter() })
    println('A')
    println("é".single().code)
    println(('a'..'z').filter { it.code % 5 == 0 })
    println("abc".all { it in 'a'..'c' })
    println('x'.toString() + 'y')
    println("zebra".toList().sorted())
    println("abc".sumOf { it.code })
    println('9' - '0')
    println('a'.isLetter() && !'a'.isDigit())
    val chars = charArrayOf('d', 'a', 'c')
    chars.sort()
    println(String(chars))
    println('a'.plus(2))
    println('b'.minus(1))
    println(Char.MAX_VALUE.code)
}
